## ✅ 4. Základní kód – `main.c`

```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Nastavení
#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define GRID_SIZE 20  // Velikost jednoho dílku (pixelů)
#define GRID_WIDTH (SCREEN_WIDTH / GRID_SIZE)
#define GRID_HEIGHT (SCREEN_HEIGHT / GRID_SIZE)
#define SNAKE_MAX_LENGTH (GRID_WIDTH * GRID_HEIGHT)
#define FRAME_DELAY 100  // ms – rychlost hry

// Směry
typedef enum {
    DIR_UP,
    DIR_DOWN,
    DIR_LEFT,
    DIR_RIGHT
} Direction;

// Struktura pro hada
typedef struct {
    int x, y;
} Point;

// Globální proměnné
SDL_Window* window = NULL;
SDL_Renderer* renderer = NULL;
SDL_Texture* tex_head = NULL;
SDL_Texture* tex_body = NULL;
SDL_Texture* tex_tail = NULL;
SDL_Texture* tex_food = NULL;
SDL_Texture* tex_background = NULL;

Point snake[SNAKE_MAX_LENGTH];
int snake_length;
Direction dir;
Direction next_dir;
Point food;
bool game_running;
Uint32 last_move_time;
```

