### ✅ 6. Inicializace hry

```c
bool init() {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL nelze inicializovat: %s\n", SDL_GetError());
        return false;
    }

    window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                              SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window) {
        printf("Nelze vytvořit okno: %s\n", SDL_GetError());
        return false;
    }

    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Nelze vytvořit renderer: %s\n", SDL_GetError());
        return false;
    }

    // Načti obrázky pomocí SDL_image
    tex_background = load_texture("textures/background.png");
    tex_head = load_texture("textures/head.png");
    tex_body = load_texture("textures/body.png");
    tex_tail = load_texture("textures/tail.png");
    tex_food = load_texture("textures/food.png");

    if (!tex_background || !tex_head || !tex_body || !tex_tail || !tex_food) {
        return false;
    }

    return true;
}
```

