### ✅ 7. Restart hry

```c
void reset_game() {
    // Startovní pozice
    snake_length = 3;
    snake[0].x = GRID_WIDTH / 2;
    snake[0].y = GRID_HEIGHT / 2;
    for (int i = 1; i < snake_length; i++) {
        snake[i].x = snake[i-1].x;
        snake[i].y = snake[i-1].y + 1;
    }

    dir = DIR_UP;
    next_dir = DIR_UP;
    game_running = true;

    // Vygeneruj jídlo
    food.x = rand() % GRID_WIDTH;
    food.y = rand() % GRID_HEIGHT;

    last_move_time = SDL_GetTicks();
}
```

---

### ✅ 8. Generování jídla (bez kolize s hadem)

```c
void spawn_food() {
    bool valid;
    do {
        valid = true;
        food.x = rand() % GRID_WIDTH;
        food.y = rand() % GRID_HEIGHT;

        for (int i = 0; i < snake_length; i++) {
            if (snake[i].x == food.x && snake[i].y == food.y) {
                valid = false;
                break;
            }
        }
    } while (!valid);
}
```

