### ✅ 9. Aktualizace hada

```c
void update_snake() {
    Uint32 current_time = SDL_GetTicks();
    if (current_time - last_move_time < FRAME_DELAY) return;

    dir = next_dir;
    last_move_time = current_time;

    // Posun hada – odzadu
    for (int i = snake_length - 1; i > 0; i--) {
        snake[i] = snake[i - 1];
    }

    // Pohyb hlavy
    switch (dir) {
        case DIR_UP:    snake[0].y--; break;
        case DIR_DOWN:  snake[0].y++; break;
        case DIR_LEFT:  snake[0].x--; break;
        case DIR_RIGHT: snake[0].x++; break;
    }

    // Kolize s okrajem
    if (snake[0].x < 0 || snake[0].x >= GRID_WIDTH ||
        snake[0].y < 0 || snake[0].y >= GRID_HEIGHT) {
        game_running = false;
        return;
    }

    // Kolize se sebou
    for (int i = 1; i < snake_length; i++) {
        if (snake[0].x == snake[i].x && snake[0].y == snake[i].y) {
            game_running = false;
            return;
        }
    }

    // Kolize s jídlem
    if (snake[0].x == food.x && snake[0].y == food.y) {
        snake_length++;
        if (snake_length >= SNAKE_MAX_LENGTH) {
            game_running = false; // Vyhrál
        } else {
            spawn_food();
        }
    }
}
```

