### ✅ 10. Vykreslování

```c
void render() {
    SDL_RenderClear(renderer);

    // Vykresli pozadí
    SDL_Rect bg_rect = {0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
    SDL_RenderCopy(renderer, tex_background, NULL, &bg_rect);

    // Vykresli hada
    for (int i = 0; i < snake_length; i++) {
        SDL_Texture* texture = tex_body;
        if (i == 0) texture = tex_head;
        else if (i == snake_length - 1) texture = tex_tail;

        SDL_Rect rect = {
            snake[i].x * GRID_SIZE,
            snake[i].y * GRID_SIZE,
            GRID_SIZE,
            GRID_SIZE
        };
        SDL_RenderCopy(renderer, texture, NULL, &rect);
    }

    // Vykresli jídlo
    SDL_Rect food_rect = {
        food.x * GRID_SIZE,
        food.y * GRID_SIZE,
        GRID_SIZE,
        GRID_SIZE
    };
    SDL_RenderCopy(renderer, tex_food, NULL, &food_rect);

    SDL_RenderPresent(renderer);
}
```

