### ✅ 11. Hlavní smyčka

```c
int main(int argc, char* argv[]) {
    srand(SDL_GetTicks());

    if (!init()) {
        printf("Inicializace selhala!\n");
        return 1;
    }

    reset_game();

    SDL_Event e;
    bool quit = false;

    while (!quit) {
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                quit = true;
            }
            else if (e.type == SDL_KEYDOWN) {
                switch (e.key.keysym.sym) {
                    case SDLK_UP:
                        if (dir != DIR_DOWN) next_dir = DIR_UP;
                        break;
                    case SDLK_DOWN:
                        if (dir != DIR_UP) next_dir = DIR_DOWN;
                        break;
                    case SDLK_LEFT:
                        if (dir != DIR_RIGHT) next_dir = DIR_LEFT;
                        break;
                    case SDLK_RIGHT:
                        if (dir != DIR_LEFT) next_dir = DIR_RIGHT;
                        break;
                    case SDLK_r:
                        if (!game_running) reset_game();
                        break;
                }
            }
        }

        if (game_running) {
            update_snake();
        }

        render();

        SDL_Delay(10);  // Bez čekání na 60 FPS
    }

    // Uvolnění prostředků
    SDL_DestroyTexture(tex_background);
    SDL_DestroyTexture(tex_head);
    SDL_DestroyTexture(tex_body);
    SDL_DestroyTexture(tex_tail);
    SDL_DestroyTexture(tex_food);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    IMG_Quit();
    SDL_Quit();

    return 0;
}
```

